    [Theory]
    [MemberData(nameof(Mistakes))]
    public void ALoopStoppingOneShortOfItsGuardIsFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The triangles going up to r; a guard that only repeats the loop's own bound, with nothing read one place back; each
    /// number summed with its neighbours, the last one guarded with n - 1; each row made from the one before with a 0 put
    /// at each end; and neighbouring pairs summed, the loop one short of the row on purpose.
    /// </summary>
    [Theory]
    [InlineData("pascal.c", "#include <stdio.h>\n\nint main(void) {\n    int rows[5][6] = {{1}};\n    int lengths[5] = {1};\n    for (int r = 1; r < 5; r++) {\n        for (int c = 0; c < r + 1; c++) {\n            int upleft = c > 0 ? rows[r - 1][c - 1] : 0;\n            int upright = c < r ? rows[r - 1][c] : 0;\n            rows[r][c] = upleft + upright;\n            lengths[r] = c + 1;\n        }\n    }\n    for (int r = 0; r < 5; r++) {\n        if (r > 0) printf(\"|\");\n        for (int c = 0; c < lengths[r]; c++) printf(c > 0 ? \" %d\" : \"%d\", rows[r][c]);\n    }\n    printf(\"\\n\");\n    return 0;\n}\n")]
    [InlineData("pascal.cpp", "#include <iostream>\n#include <vector>\n\nstd::vector<std::vector<int>> pascal(int n) {\n    std::vector<std::vector<int>> rows = {{1}};\n    for (int r = 1; r < n; r++) {\n        std::vector<int> row;\n        for (int c = 0; c < r + 1; c++) {\n            int upleft = c > 0 ? rows[r - 1].at(c - 1) : 0;\n            int upright = c < r ? rows[r - 1].at(c) : 0;\n            row.push_back(upleft + upright);\n        }\n        rows.push_back(row);\n    }\n    return rows;\n}\n\nint main() {\n    std::vector<std::vector<int>> rows = pascal(5);\n    for (std::size_t r = 0; r < rows.size(); r++) {\n        if (r > 0) std::cout << \"|\";\n        for (std::size_t c = 0; c < rows[r].size(); c++) std::cout << (c > 0 ? \" \" : \"\") << rows[r][c];\n    }\n    std::cout << std::endl;\n    return 0;\n}\n")]
    [InlineData("pascal.dart", "List<List<int>> pascal(int n) {\n  final rows = [\n    [1]\n  ];\n  for (var r = 1; r < n; r++) {\n    final row = <int>[];\n    for (var c = 0; c < r + 1; c++) {\n      final upleft = c > 0 ? rows[r - 1][c - 1] : 0;\n      final upright = c < r ? rows[r - 1][c] : 0;\n      row.add(upleft + upright);\n    }\n    rows.add(row);\n  }\n  return rows;\n}\n\nvoid main() {\n  print(pascal(5).map((row) => row.join(' ')).join('|'));\n}\n")]
