    [InlineData("pascal.exs", "defmodule Pascal do\n  def next_row(previous, r) do\n    for c <- 0..r, do: (if c > 0, do: Enum.at(previous, c - 1), else: 0) + (if c < r, do: Enum.at(previous, c), else: 0)\n  end\n\n  def rows(n), do: Enum.scan(1..(n - 1), [1], fn r, previous -> next_row(previous, r) end) |> then(&[[1] | &1])\nend\n\nIO.puts(Pascal.rows(5) |> Enum.map(&Enum.join(&1, \" \")) |> Enum.join(\"|\"))\n")]
